    public static class GabrieleDAnnunzio
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Ardisco non ordisco.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Arma la prora e salpa verso il Mondo.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Il mondo è la rappresentazione della sensibilità e del pensiero di pochi uomini superiori.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Il piacere è il più certo mezzo di conoscimento offertoci dalla Natura e [...] colui il quale molto ha sofferto è men sapiente di colui il quale ha molto gioito.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Io ho quel che ho donato perché nella vita ho sempre amato.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Io intendo rimanere al Polo: voi mi lascerete lassù. Un uomo come me non può morire in un cataletto. Egli deve scomparire nel mistero di una leggenda. lo diverrò l'asse della Terra.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Io sono un animale di lusso; e il superfluo m'è necessario come il respiro.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "L'automobile è femmina.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "L'uomo è, sopra tutto, un animale accomodativo. Non c'è turpitudine o dolore a cui non s'adatti.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Lo stile è potenza isolatrice.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Non ritroverete mai la vostra donna -amata, amante- così com'era quando da lei vi separaste.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Non temere! Accogli l'ignoto e l'impreveduto e quanto altro ti recherà l'evento; abolisci ogni divieto; procedi sicuro e libero. Non avere omai sollecitudine se non di vivere. Il tuo fato non potrà compiersi se non nella profusione della vita.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "O beati quelli che più hanno, perché più potranno dare, più potranno ardere.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Osare l'inosabile.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Ricordati di osare sempre.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Tutto, infatti, è qui da me creato o trasfigurato. Tutto qui mostra le impronte del mio stile, nel senso che io voglio dare allo stile.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Una bella donna è mille volte più attraente quando esce dalle braccia di Morfeo che dopo un'accurata toilette.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Le mie passioni sono le mie virtù.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Prima, circa una trentina d'anni fa, tutte le donne erano brune, d'un bruno profondo e fatale, 'mer d'ébène noir ocèan, pavillon de ténèbres tendues', come cantava Carlo Baudelaire. Ora, invece, una donna che non è bionda non è una donna.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "È insipida la gioia che non abbia in sé una promessa di dolore.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Il viso dell'amore è osceno come quello di un pagliaccio vinoso.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Ignudo le membra agilissime a'l sole ed a l'acqua.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "A 'l mare, a 'l mare, Lalla, a 'l mio libero tristo fragrante verde Adriatico.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Chiedon l'esametro lungo salente i fantasmi che su dal core baldi mi fioriscono, e l'onda armonica al breve pentametro spira in un pispiglio languido di dattili.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Ma ancora ancor mi tentan le spire volubili tue, o alata strofe, coppia di serpentelli alati.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Quando un grande poeta volge la fronte verso l'Eternità, la mano pia che gli chiude gli occhi sembra suggellare sotto le esangui palpebre la più luminosa parte della bellezza terrena.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "L'anima della terra è notturna, ma la luce del sole la nasconde più che non la nasconda la tenebra.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Un fiotto di sanità caldo la riempiva; certe sùbite gioie di vivere le muovevano il sangue, le mettevano nel petto quasi dei battimenti d'ale, le mettevano de' canti nella bocca.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Solo il sambuco odorava dalle ampie antele candide fresco e mite, là entro. Le farfalle passavano fuggevoli; gruppi di chiocciole andavano qua e là strisciando tra le piante succose, lasciando le righe lucenti.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Pensò la lentezza del dormiveglia, l'indugio del sopore verso l'alba, quando la volontà velata guida leggermente il sogno felice.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Bisogna fare'' la propria vita, come si fa un'opera d'arte. Bisogna che la vita d'un uomo d'intelletto sia opera di lui. La superiorità vera è tutta qui.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Bisogna conservare ad ogni costo intiera la libertà, fin nell'ebrezza. La regola dell'uomo d'intelletto, eccola: ― Habere, non haberi.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Aveva la voce così insinuante che quasi dava la sensazione d'una carezza carnale; e aveva quello sguardo involontariamente amoroso e voluttuoso che turba tutti li uomini e ne accende d'improvviso la brama.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Da certi suoni della voce e del riso, da certi gesti, da certe attitudini, da certi sguardi ella esalava, forse involontariamente, un fascino troppo afrodisiaco.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Certo, quanto più la cosa da un uom posseduta suscita nelli altri l'invidia e la brama, tanto più l'uomo ne gode e n'è superbo.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Quell'aria aspettava il 'suo' respiro; quei tappeti chiedevano d'esser premuti dal 'suo' piede; quei cuscini volevano l'impronta del 'suo' corpo.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Il verso è tutto.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "'Schifanoja' in Ferrara (oh gloria d'Este!), ove il Cossa emulò Cosimo Tura in trionfi d'iddii su per le mura, non vide mai tanto gioconde feste.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Io vi amo come nessuna parola umana potrà mai esprimere. Ho bisogno di voi. Voi soltanto siete 'vera'; voi siete la Verità che il mio spirito cerca. Il resto è vano; il resto è nulla.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Io sono camaleontico, chimerico, incoerente, inconsistente. Qualunque mio sforzo verso l'unità riuscirà sempre vano. Bisogna omai ch'io mi rassegni. La mia legge è in una parola: NUNC. Sia fatta la volontà della legge.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "[...] e credere in te 'soltanto', giurare in te 'soltanto', riporre in te 'soltanto' la mia fede, la mia forza, il mio orgoglio, tutto il mio mondo, tutto quel che sogno, e tutto quel che spero....", Author = "Gabriele D'Annunzio" },
        };
    }
}